import React, { useCallback, useState } from 'react';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { RuntimeFilterOp } from '@thoughtspot/visual-embed-sdk';
import { THOUGHTSPOT_LIVEBOARD_ID, TOP_HEADER_PX } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

const BST_BLUE = '#1D3FA8';
const EMBED_MIN_H = `calc(100vh - ${TOP_HEADER_PX}px - 220px)`;

interface FilterGroup {
  /** Must match the exact column name in your ThoughtSpot data model */
  column: string;
  label: string;
  values: string[];
}

// Update column names and values to match your ThoughtSpot model
const FILTER_GROUPS: FilterGroup[] = [
  {
    column: 'Plant',
    label: 'Plant',
    values: ['Hamburg', 'Munich', 'Berlin', 'Frankfurt', 'Cologne'],
  },
  {
    column: 'Driver',
    label: 'Driver',
    values: ['Schmidt', 'Mueller', 'Weber', 'Bauer', 'Fischer'],
  },
];

interface LiveboardTabPageProps {
  title: string;
  description?: string;
  tabId: string;
}

function FilterIcon() {
  return (
    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
      <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3" />
    </svg>
  );
}

export default function LiveboardTabPage({ title, description, tabId }: LiveboardTabPageProps) {
  const { hiddenActions, disabledActions } = useTier();
  const [activeFilters, setActiveFilters] = useState<Record<string, string[]>>({});

  const toggleValue = (column: string, value: string) => {
    setActiveFilters(prev => {
      const current = prev[column] ?? [];
      const next = current.includes(value)
        ? current.filter(v => v !== value)
        : [...current, value];
      return { ...prev, [column]: next };
    });
  };

  const clearAll = () => setActiveFilters({});

  const hasAnyFilter = Object.values(activeFilters).some(v => v.length > 0);

  const runtimeFilters = FILTER_GROUPS
    .filter(g => (activeFilters[g.column] ?? []).length > 0)
    .map(g => ({
      columnName: g.column,
      operator: RuntimeFilterOp.IN,
      values: activeFilters[g.column],
    }));

  // Key changes whenever filters change → re-mounts embed with new runtimeFilters
  const embedKey = `${tabId}-${JSON.stringify(activeFilters)}`;

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error(`[ThoughtSpot Liveboard – ${title}]`, formatThoughtSpotEmbedError(err), err);
  }, [title]);

  return (
    <div style={{ backgroundColor: BST_BLUE, minHeight: `calc(100vh - ${TOP_HEADER_PX}px)` }}>

      {/* Blue header banner */}
      <div style={{ padding: '1.75rem 2.5rem 1.25rem' }}>
        <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.55)', marginBottom: 6 }}>BST Media</div>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: '#ffffff', margin: 0 }}>{title}</h1>
        {description && (
          <p style={{ fontSize: 14, color: 'rgba(255,255,255,0.75)', margin: '6px 0 0', maxWidth: 640 }}>
            {description}
          </p>
        )}
      </div>

      {/* Native filter bar — rectangular chips, distinct from dashboard pill style */}
      <div
        style={{
          margin: '0 2.5rem 1rem',
          padding: '12px 16px',
          backgroundColor: 'rgba(0,0,0,0.18)',
          borderRadius: 10,
          display: 'flex',
          flexDirection: 'column',
          gap: 10,
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, color: 'rgba(255,255,255,0.6)', fontSize: 11, fontWeight: 600, letterSpacing: '0.08em', textTransform: 'uppercase' }}>
            <FilterIcon />
            Filters
          </div>
          {hasAnyFilter && (
            <button
              type="button"
              onClick={clearAll}
              style={{ background: 'none', border: 'none', color: 'rgba(255,255,255,0.55)', fontSize: 11, cursor: 'pointer', textDecoration: 'underline', padding: 0 }}
            >
              Clear all
            </button>
          )}
        </div>

        {FILTER_GROUPS.map(group => (
          <div key={group.column} style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
            <span style={{ fontSize: 11, fontWeight: 600, color: 'rgba(255,255,255,0.5)', minWidth: 44, textTransform: 'uppercase', letterSpacing: '0.06em' }}>
              {group.label}
            </span>
            {group.values.map(value => {
              const isActive = (activeFilters[group.column] ?? []).includes(value);
              return (
                <button
                  key={value}
                  type="button"
                  onClick={() => toggleValue(group.column, value)}
                  style={{
                    padding: '4px 11px',
                    borderRadius: 4,
                    border: `1px solid ${isActive ? 'rgba(255,255,255,0.9)' : 'rgba(255,255,255,0.25)'}`,
                    background: isActive ? 'rgba(255,255,255,0.22)' : 'transparent',
                    color: isActive ? '#ffffff' : 'rgba(255,255,255,0.65)',
                    fontSize: 12,
                    fontWeight: isActive ? 600 : 400,
                    cursor: 'pointer',
                    transition: 'all 0.12s ease',
                  }}
                >
                  {isActive && <span style={{ marginRight: 4, fontSize: 10 }}>✓</span>}
                  {value}
                </button>
              );
            })}
          </div>
        ))}
      </div>

      {/* Embed card */}
      <div style={{ padding: '0 2.5rem 2rem' }}>
        <div
          style={{
            backgroundColor: '#ffffff',
            borderRadius: 12,
            border: 'none',
            minHeight: EMBED_MIN_H,
            overflow: 'visible',
          }}
        >
          <LiveboardEmbed
            key={embedKey}
            liveboardId={THOUGHTSPOT_LIVEBOARD_ID}
            activeTabId={tabId}
            visibleTabs={[tabId]}
            fullHeight
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            onError={onError}
            runtimeFilters={runtimeFilters}
            isLiveboardStylingAndGroupingEnabled
            isLiveboardCompactHeaderEnabled
            additionalFlags={{ enable2ColumnLayout: true }}
            style={{ width: '100%', minHeight: EMBED_MIN_H, display: 'block', border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
